// ─── IMPORT ─────────────────────────────────────────────────────────────────

function importCollection(def) {
  console.log(`[${def.name}] creating collection...`);
  const collection = figma.variables.createVariableCollection(def.name);

  const modeIds = {};
  const [firstMode, ...restModes] = def.modes;
  modeIds[firstMode] = collection.defaultModeId;
  collection.renameMode(collection.defaultModeId, firstMode);
  for (const modeName of restModes) {
    modeIds[modeName] = collection.addMode(modeName);
  }
  console.log(`[${def.name}] modes:`, def.modes.join(", "));

  for (const v of def.variables) {
    try {
      const variable = figma.variables.createVariable(v.name, collection, v.type);
      for (const modeName of def.modes) {
        variable.setValueForMode(modeIds[modeName], v.values[modeName]);
      }
      if (v.description) variable.description = v.description;
      console.log(`[${def.name}] ✓ "${v.name}"`);
    } catch (err) {
      console.error(`[${def.name}] ✗ "${v.name}" failed:`, err.message);
      throw err;
    }
  }

  console.log(`[${def.name}] done`);
}

// ─── UI: COLLECTION SELECTION ───────────────────────────────────────────────

figma.showUI(__html__, { width: 320, height: 400 });

figma.ui.postMessage({
  type: "init",
  collections: tokenCollections.map((c) => ({ name: c.name, count: c.variables.length })),
});

figma.ui.onmessage = (msg) => {
  if (msg.type !== "import") return;

  try {
    console.log("=== Import Variables ===");
    const selected = tokenCollections.filter((c) => msg.names.includes(c.name));
    for (const def of selected) {
      importCollection(def);
    }
    console.log("=== Complete ===");
    figma.notify(`✅ Imported ${selected.length} collection(s) successfully!`);
  } catch (err) {
    console.error("=== Failed ===", err.message);
    figma.notify("❌ " + err.message, { error: true });
  } finally {
    figma.closePlugin();
  }
};
